#include <bits/stdc++.h>
using namespace std;

int N, M;
int adj[20];
vector<long long> memo;

long long countIndependent(int mask) {
    if (mask == 0) return 1;

    long long &res = memo[mask];
    if (res != -1) return res;

    int v = __builtin_ctz(mask);
    int bit = 1 << v;

    res = countIndependent(mask & ~bit);
    res += countIndependent(mask & ~bit & ~adj[v]);

    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> M;

    for (int i = 0; i < M; i++) {
        int x, y;
        cin >> x >> y;
        --x;
        --y;
        adj[x] |= (1 << y);
        adj[y] |= (1 << x);
    }

    memo.assign(1 << N, -1);

    long long ans = countIndependent((1 << N) - 1) - 1;
    cout << ans << '\n';

    return 0;
}
